using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;

namespace TabStudio.Debugging.Instrumentation;

/// <summary>Recognizes generated source files, which the debugger never instruments or stops in.</summary>
internal static class GeneratedCode
{
    private static readonly string[] GeneratedSuffixes = [".g.cs", ".g.i.cs", ".designer.cs", ".generated.cs"];

    /// <summary>
    /// Whether a tree is generated: its file name ends like the SDK's generated files (such as
    /// <c>obj/App.GlobalUsings.g.cs</c>), or it starts with an <c>&lt;auto-generated&gt;</c> comment.
    /// </summary>
    public static bool IsGenerated(SyntaxTree tree, CancellationToken cancellationToken)
    {
        var name = Path.GetFileName(tree.FilePath);
        if (GeneratedSuffixes.Any(suffix => name.EndsWith(suffix, StringComparison.OrdinalIgnoreCase)))
        {
            return true;
        }

        foreach (var trivia in tree.GetRoot(cancellationToken).GetLeadingTrivia())
        {
            if ((trivia.IsKind(SyntaxKind.SingleLineCommentTrivia) || trivia.IsKind(SyntaxKind.MultiLineCommentTrivia)) &&
                trivia.ToString().Contains("<auto-generated", StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return false;
    }
}
